/* CHICO GENERAL TEAM / STUDIO 4.0 — standalone, no legacy global state. */
'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=x=>escapeHTML(x);
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2});
const fDate=s=>String(s||'').slice(0,10);
const valOrDash=(n,valid)=>valid?fmt(n):'—';
const ranks=['Responsible','Administrator','Moderator','SN.Helper','Helper'];
const names={dashboard:'لوحة القيادة',roster:'إدارة الفريق',daily:'تسجيل الإحصائيات',server:'إحصائيات السيرفر',reports:'تقارير CHICO',week:'إغلاق الأسبوع',settings:'الإعدادات'};
const glyphs={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',ticket:'<path d="M2 9a3 3 0 0 0 0 6v3a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-3a3 3 0 0 1 0-6V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v3Z"/><path d="M13 4v2m0 4v4m0 4v2"/>',flag:'<path d="M4 22V4m0 1c4-4 8 4 16 0v12c-8 4-12-4-16 0"/>',chart:'<path d="M3 3v18h18"/><path d="m7 16 4-5 3 3 6-8"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-1.83 1.83-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V20h-2.6v-.09A1.65 1.65 0 0 0 11 18.4a1.65 1.65 0 0 0-1.82.33l-.06.06-1.83-1.83.06-.06a1.65 1.65 0 0 0 .33-1.82A1.65 1.65 0 0 0 6.17 14H6v-2.6h.09A1.65 1.65 0 0 0 7.6 10a1.65 1.65 0 0 0-.33-1.82l-.06-.06 1.83-1.83.06.06a1.65 1.65 0 0 0 1.82.33A1.65 1.65 0 0 0 12 5.17V5h2.6v.09A1.65 1.65 0 0 0 16 6.6a1.65 1.65 0 0 0 1.82-.33l.06-.06 1.83 1.83-.06.06a1.65 1.65 0 0 0-.33 1.82A1.65 1.65 0 0 0 20.83 11H21v2.6h-.09A1.65 1.65 0 0 0 19.4 15Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',edit:'<path d="M12 20h9M16 5l3 3M4 20l4-1 11-11a2.1 2.1 0 0 0-3-3L5 16z"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 15h10l1-15M10 11v6M14 11v6"/>',search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/>',chevron:'<path d="m9 18 6-6-6-6"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3"/><path d="M11 3h8a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-8"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.5 9A7 7 0 0 1 18 7l2 2M4 15l2 2a7 7 0 0 0 12.5-2"/>',moon:'<path d="M20.4 15.7A9 9 0 0 1 8.3 3.6 9 9 0 1 0 20.4 15.7Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',x:'<path d="M18 6 6 18M6 6l12 12"/>',eye:'<path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',shield:'<path d="m12 22 1-1c5-2 7-5 7-10V5l-8-3-8 3v6c0 5 2 8 7 10Z"/><path d="m9 12 2 2 4-4"/>',upload:'<path d="M12 16V3M7 8l5-5 5 5M4 17v3a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-3"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v3a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-3"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>',alert:'<path d="m10.3 3.9-8.1 14a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3l-8.1-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',lock:'<rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/>',star:'<path d="m12 2 3.1 6.4 7.1 1-5.1 5 1.2 7-6.3-3.4-6.3 3.4 1.2-7-5.1-5 7.1-1Z"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',swap:'<path d="m16 3 4 4-4 4M20 7H4m4 14-4-4 4-4M4 17h16"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',arrow:'<path d="M19 12H5m7-7-7 7 7 7"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',save:'<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2Z"/><path d="M17 21v-8H7v8M7 3v5h8"/>'};
function I(name,cls=''){return `<svg class="icon ${cls}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" role="presentation" aria-hidden="true">${glyphs[name]||glyphs.info}</svg>`}
const UI={token:'',data:null,page:'dashboard',theme:localStorage.getItem('chico_theme')||'dark',query:'',rank:'all',active:'all',selected:new Set(),dailyTab:'manual',excel:null,importMapping:{},weekRange:null,reportType:'weekly',reportDate:null,reportPreview:null,backups:null};
document.body.dataset.theme=UI.theme;
const STORAGE='chico_session_4';
try{UI.token=sessionStorage.getItem(STORAGE)||''}catch{}
function saveToken(t){UI.token=t;try{if(t)sessionStorage.setItem(STORAGE,t);else sessionStorage.removeItem(STORAGE)}catch{}}
function toast(msg,err=false){const e=$('#toast');e.textContent=String(msg);e.className='toast '+(err?'error':'success');e.hidden=false;clearTimeout(toast._t);toast._t=setTimeout(()=>e.hidden=true,4600)}
async function API(path,body=null){const options={method:body===null?'GET':'POST',headers:{'Authorization':'Bearer '+UI.token}};if(body!==null){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}let resp;try{resp=await fetch('/api/'+path,options)}catch{throw new Error('تعذّر الاتصال بسيرفر CHICO. راجع الاتصال وجرب تاني.')}let out;try{out=await resp.json()}catch{throw new Error('رد غير متوقع من السيرفر')}if(!resp.ok){if(resp.status===401&&path!=='login'){saveToken('');showLogin();}throw new Error(out.error||'تعذّر إتمام العملية')}return out}
async function refresh(silent=false){try{const state=await API('state');UI.data=state;UI.reportPreview=null;const conn=$('#connection');conn.innerHTML='<span></span> متصل';conn.className='connection online';render();if(!silent)toast('اتحدثت بيانات CHICO')}catch(e){const conn=$('#connection');conn.innerHTML='<span></span> غير متصل';conn.className='connection offline';if(!silent)toast(e.message,true);if(!UI.data)$('#content').innerHTML=empty('alert','تعذّر تحميل بيانات السيرفر','راجع الاتصال أو إعداد قاعدة البيانات.','<button class="btn btn-accent" data-action="refresh">إعادة المحاولة</button>')}}
function showLogin(){UI.data=null;$('#login').hidden=false;$('#shell').hidden=true;$('#password').value='';}
function showApp(){$('#login').hidden=true;$('#shell').hidden=false;refresh(true)}
const tabs=[['dashboard','لوحة القيادة','grid'],['roster','إدارة الفريق','users'],['daily','تسجيل الإحصائيات','ticket'],['server','إحصائيات السيرفر','chart'],['reports','تقارير CHICO','file'],['week','إغلاق الأسبوع','calendar'],['settings','الإعدادات','settings']];
function nav(){const item=([id,label,icon])=>`<button type="button" data-route="${id}" class="nav-btn ${UI.page===id?'active':''}"><span class="nav-i">${I(icon,'icon-lg')}</span><span>${label}</span></button>`;$('#navigation').innerHTML=tabs.map(item).join('');const quick=['dashboard','roster','daily','reports','settings'];$('#mobile-nav').innerHTML=tabs.filter(x=>quick.includes(x[0])).map(([id,label,icon])=>`<button class="quick ${UI.page===id?'active':''}" data-route="${id}">${I(icon)}<span>${label.replace('إحصائيات','إحصائيات')}</span></button>`).join('')}
function go(page){if(!names[page])return;UI.page=page;UI.reportPreview=null;UI.selected.clear();UI.query='';closeSidebar();render();window.scrollTo(0,0)}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#mobile-scrim').classList.remove('open')}
function head(kicker,title,description,actions=''){return `<div class="heading-row"><div><div class="section-overline">${kicker}</div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="page-ops">${actions}</div>`:''}</div>`}
function btn(label,action,icon='plus',klass='btn'){return `<button type="button" class="${klass}" data-action="${action}">${I(icon)} ${label}</button>`}
function badge(t,cls='muted'){return `<span class="badge badge-${cls}">${t}</span>`}
function empty(icon,title,desc,action=''){return `<div class="empty"><div class="empty-icon">${I(icon,'icon-lg')}</div><strong>${title}</strong><p>${desc}</p>${action}</div>`}
function stat(label,number,valid,foot,icon){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${I(icon)}</span></div><div class="stat-number">${valid?number:'—'}</div><div class="stat-foot">${foot}</div></div>`}
function info(message,icon='info'){return `<div class="callout">${I(icon)} <span>${message}</span></div>`}
function card(title,sub,content,action=''){return `<section class="card"><div class="card-h"><div><div class="card-title">${title}</div>${sub?`<div class="card-sub">${sub}</div>`:''}</div>${action}</div><div class="card-divider"></div>${content}</section>`}
const memberList=()=>UI.data?.members||[];
function hasStats(){return memberList().some(m=>(m.entry_count||0)>0||(m.daily_ratings||[]).length>0)}
function metricValue(n,valid){return valid?fmt(n):'—'}
function metricCards(){const t=UI.data.totals,yes=hasStats();return `<div class="stats-grid">${stat('إجمالي Tickets',metricValue(t.tickets,t.tickets_observations>0),t.tickets_observations>0,'تذاكر السيرفر هذا الأسبوع','ticket')}${stat('Weekly Flags',metricValue(t.flags,t.flags_observations>0),t.flags_observations>0,'الفلاجات المضافة هذا الأسبوع','flag')}${stat('Flag Rate',t.flag_rate===null?'—':fmt(t.flag_rate)+'%',t.flag_rate!==null,'Flags ÷ Tickets × 100','chart')}${stat('Rating',t.rate===null?'—':Number(t.rate).toFixed(2),t.rate!==null,'التقييم المسجل من 5','star')}</div>`}
function rankDistribution(){const total=memberList().length;return `<div class="rank-bars">${ranks.map(rank=>{const n=memberList().filter(m=>m.rank===rank).length;return `<div class="rank-row"><span class="rank-txt">${safe(rank)}</span><div class="rank-meter"><span style="width:${total?Math.round(100*n/total):0}%"></span></div><b>${n}</b></div>`}).join('')}</div>`}
function memberBadge(m){return `<span class="rank-label">${safe(m.rank)}</span>`}
function flagChip(m){if(!m.entry_count)return '<span class="no-data" style="font-size:18px">—</span>';if(m.flags===0)return badge('0 · سليم','good');if(m.flags>7)return badge(fmt(m.flags)+' · مرتفع','bad');if(m.flags>5)return badge(fmt(m.flags)+' · متابعة','warn');return `<span class="mono">${fmt(m.flags)}</span>`}
function ratingChip(m){if(m.rate===null)return '<span class="subtle">—</span>';return `<span class="badge badge-${m.rate>=4.8?'good':'bad'}">${Number(m.rate).toFixed(2)}</span>`}
function recentRoster(limit=6){const rows=memberList().filter(m=>m.active).slice(0,limit);return rows.length?`<div class="roster-mini">${rows.map(m=>`<div class="member-line"><div class="avatar">${safe(m.name.slice(0,2).toUpperCase())}</div><strong>${safe(m.name)}</strong>${memberBadge(m)}<button type="button" class="btn btn-small btn-ghost btn-square" data-member="${m.id}">${I('chevron')}</button></div>`).join('')}</div>`:empty('users','الفريق فاضي','أضف أول إداري وحدد رتبته.',btn('إضافة إداري','add-member'))}
function alertItems(){return memberList().filter(m=>m.entry_count&&m.flags>10||m.rate!==null&&m.rate<4.8).sort((a,b)=>b.flags-a.flags)}
function rankingFor(list){const x=list.filter(m=>m.active&&m.entry_count).sort((a,b)=>b.tickets-a.tickets).slice(0,3);return x.length?`<div class="leaderboard">${x.map((m,i)=>`<div class="leader"><span class="place">0${i+1}</span><strong>${safe(m.name)}</strong>${memberBadge(m)}<span class="score">${fmt(m.tickets)}</span></div>`).join('')}</div>`:empty('star','التوب لسه فاضي','هنا هيظهر الترتيب بعد تسجيل Tickets.')}
function dashboard(){const d=UI.data,w=d.week,alerts=alertItems();return head('SERVER / COMMAND','لوحة القيادة','كل ما يخص فريق CHICO ME في مكان واحد.',`${btn('تسجيل قراءة','new-entry','plus','btn btn-accent')}${btn('إدارة الفريق','go-roster','users')}`)+`<section class="command-strip"><div><div class="overline">CHICO / WEEKLY CONTROL</div><h2>أسبوع اللعبة الحالي</h2><p>تذاكر • فلاجات • تقييمات • رتب الإداريين</p></div><div class="command-right"><span class="week-signal">${safe(fDate(w.starts))}<br>→ ${safe(fDate(w.ends))}</span><img src="/assets/chico-wolf-safe-192.png" alt="CHICO"></div></section>${metricCards()}${!hasStats()?`<div class="callout" style="margin-bottom:17px">${I('info')} <span><strong>مفيش إحصائيات مسجلة.</strong> الموجود حاليًا هو أسماء الفريق ورتبهم فقط. ابدأ بتسجيل أول قراءة أو ارفع Excel.</span>${btn('رفع Excel','go-excel','upload','btn btn-small')}</div>`:''}<div class="dashboard-grid"><div class="stack">${hasStats()?card('حالات تحتاج متابعة','الإداريون الأكثر من 10 Flags أو تقييم أقل من 4.80',alerts.length?`<div class="card-p">${alerts.map(m=>`<div class="alert-line"><div><strong>${safe(m.name)}</strong><small>${safe(m.rank)}</small></div><div style="display:flex;gap:6px">${flagChip(m)} ${ratingChip(m)} <button class="btn btn-small" data-member="${m.id}">${I('chevron')}</button></div></div>`).join('')}</div>`:empty('check','مفيش تنبيهات','لا توجد حالات مسجلة تستدعي المتابعة.')):card('بداية الإحصائيات','البيانات هتظهر بمجرد التسجيل',empty('ticket','لم يتم تسجيل أي قراءة','ابدأ بأول تقرير يومي أو ارفع ملف Excel المعتمد.',`${btn('تسجيل قراءة','new-entry','plus','btn btn-accent')} ${btn('رفع Excel','go-excel','upload')}`))}${hasStats()?card('Top 3 · Helpers & SN.Helpers','أعلى تذاكر في الفئة',`<div class="card-p">${rankingFor(memberList().filter(m=>['Helper','SN.Helper'].includes(m.rank)))}</div>`):card('آخر أسماء الفريق','افتح أي إداري للتعديل والتفاصيل',recentRoster(7),btn('كل الفريق','go-roster','arrow','btn btn-small'))}</div><div class="stack">${card('توزيع الرتب','الأعضاء المسجلون في الفريق',rankDistribution(),badge(memberList().length+' إداري','gold'))}${hasStats()?card('Top 3 · Moderators','الترتيب حسب Tickets',`<div class="card-p">${rankingFor(memberList().filter(m=>m.rank==='Moderator'))}</div>`):card('إدارة سريعة','كل تفاصيل الفريق قابلة للتعديل',`<div class="card-p"><div class="info-line">${I('edit')} تعديل الاسم أو الرتبة</div><div class="info-line" style="margin-top:13px">${I('trash')} حذف الإداري أو سجلاته</div><div class="info-line" style="margin-top:13px">${I('lock')} دخول بكلمة سر واحدة</div><div style="margin-top:17px">${btn('فتح إدارة الفريق','go-roster','users','btn btn-accent')}</div></div>`)}</div></div>`}
function filteredMembers(){return memberList().filter(m=>(!UI.query||(m.name+' '+m.rank).toLowerCase().includes(UI.query.toLowerCase()))&&(UI.rank==='all'||m.rank===UI.rank)&&(UI.active==='all'||(UI.active==='active'?m.active:!m.active)))}
function rosterTable(){const ms=filteredMembers();return `<div class="table-scroll"><table class="table"><thead><tr><th class="thead-select"><input id="select-all" type="checkbox" class="check" ${ms.length&&ms.every(m=>UI.selected.has(m.id))?'checked':''}></th><th>الإداري</th><th>الرتبة</th><th>الحالة</th><th>التقارير</th><th>المناوبة</th><th>الإجراءات</th></tr></thead><tbody>${ms.length?ms.map(m=>`<tr><td><input class="check" type="checkbox" data-select-member="${m.id}" ${UI.selected.has(m.id)?'checked':''}></td><td><div class="name-cell"><span class="avatar">${safe(m.name.slice(0,2).toUpperCase())}</span><span>${safe(m.name)}<small>ID ${m.id}</small></span></div></td><td>${memberBadge(m)}</td><td>${m.active?badge('نشط','good'):badge('غير نشط','muted')}</td><td>${m.reporting?badge('ظاهر','gold'):badge('مخفي','muted')}</td><td>${m.shift?safe(m.shift):'<span class="subtle">—</span>'}</td><td><div class="row-actions"><button type="button" class="btn btn-small" data-edit-member="${m.id}" title="تعديل">${I('edit')} تعديل</button><button class="btn btn-small btn-ghost" data-member="${m.id}" title="تفاصيل">${I('eye')}</button><button class="btn btn-small btn-ghost" data-delete-member="${m.id}" title="حذف" style="color:var(--red)">${I('trash')}</button></div></td></tr>`).join(''):`<tr><td colspan="7" class="empty-row">لا يوجد إداريون مطابقون للبحث</td></tr>`}</tbody></table></div>`}
function roster(){return head('TEAM / ROSTER','إدارة الفريق','إضافة أو تعديل أو حذف أي إداري أو رتبة بسهولة.',`${btn('إضافة إداري','add-member','plus','btn btn-accent')}${btn('إزالة المحددين','bulk-delete','trash','btn btn-danger')}`)+`<div class="card card-p"><div class="toolbar"><div class="search-wrap">${I('search')}<input type="search" id="roster-search" value="${safe(UI.query)}" placeholder="ابحث باسم الإداري أو الرتبة..."></div><select id="roster-rank" class="select-compact"><option value="all">كل الرتب</option>${ranks.map(r=>`<option value="${r}" ${UI.rank===r?'selected':''}>${r}</option>`).join('')}</select><select id="roster-active" class="select-compact"><option value="all">كل الحالات</option><option value="active" ${UI.active==='active'?'selected':''}>نشط</option><option value="inactive" ${UI.active==='inactive'?'selected':''}>غير نشط</option></select>${badge(filteredMembers().length+' من '+memberList().length,'gold')}</div><div id="roster-table">${rosterTable()}</div></div>`}
function currentDay(){const w=UI.data.week,t=UI.data.today;return t<w.starts?w.starts:t>w.ends?w.ends:t}
function fieldsMember(){return memberList().filter(m=>m.rank!=='Responsible').map(m=>`<option value="${m.id}">${safe(m.name)} · ${safe(m.rank)}</option>`).join('')}
function records(){return memberList().flatMap(m=>(m.data||[]).map(r=>({...r,name:m.name,rank:m.rank}))).sort((a,b)=>b.end_on.localeCompare(a.end_on)||b.id-a.id)}
function ratingRecords(){return memberList().flatMap(m=>(m.daily_ratings||[]).map(r=>({...r,name:m.name,rank:m.rank,member_id:m.id}))).sort((a,b)=>b.evaluation_date.localeCompare(a.evaluation_date))}
function statTable(){const entries=records();return entries.length?`<div class="table-scroll"><table class="table"><thead><tr><th>الإداري</th><th>الفترة</th><th>Tickets</th><th>Flags</th><th>TIME</th><th>الإجراء</th></tr></thead><tbody>${entries.map(r=>`<tr><td><strong>${safe(r.name)}</strong><br>${memberBadge(r)}</td><td dir="ltr">${safe(r.start_on)} → ${safe(r.end_on)}</td><td class="numeric">${fmt(r.tickets)}</td><td class="numeric">${r.flags===null?'—':fmt(r.flags)}</td><td class="numeric">${r.hours===null?'—':fmt(r.hours)+'h'}</td><td><div class="row-actions"><button class="btn btn-small" data-edit-entry="${r.id}">${I('edit')} تعديل</button><button class="btn btn-small btn-ghost" style="color:var(--red)" data-delete-entry="${r.id}">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('ticket','مفيش قراءات مسجلة','بمجرد حفظ أول قراءة هتظهر هنا مع إمكانية تعديلها أو حذفها.')}
function ratingTable(){const rows=ratingRecords();return rows.length?`<div class="table-scroll"><table class="table"><thead><tr><th>الإداري</th><th>اليوم</th><th>Rating / 5</th><th>الإجراء</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${safe(r.name)}</td><td dir="ltr">${safe(r.evaluation_date)}</td><td class="numeric">${Number(r.rate).toFixed(2)}</td><td><div class="row-actions"><button class="btn btn-small" data-edit-rating="${r.id}">${I('edit')} تعديل</button><button class="btn btn-small btn-danger" data-delete-rating="${r.id}">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('star','مفيش تقييمات مسجلة','تقييم اللعبة بيتسجل بشكل مستقل عن Tickets.')}
function daily(){return head('STATS / GAME READINGS','تسجيل الإحصائيات','تقدر تدخل قراءة يدوي، ترفع Excel، تعدّل أو تمسح أي سجل.',`${btn('قراءة جديدة','new-entry','plus','btn btn-accent')}`)+`<div class="method-tabs"><button class="${UI.dailyTab==='manual'?'active':''}" data-tab="manual">${I('edit')} إدخال يدوي</button><button class="${UI.dailyTab==='excel'?'active':''}" data-tab="excel">${I('upload')} رفع Excel</button></div><div id="daily-workspace">${UI.dailyTab==='excel'?excelPanel():manualPanel()}</div><div class="section-gap">${card('سجل القراءات','كل قراءة تقدر تعدلها أو تحذفها',statTable())}</div><div class="section-gap">${card('سجل التقييمات','Rating من 5، مستقل عن تذاكر اللعبة',ratingTable())}</div>`}
function manualPanel(){return `<section class="card card-p"><div class="panel-header"><div><h2>إضافة قراءة من اللعبة</h2><small>لو التقرير بيغطي أكثر من يوم، سجّل الفترة كاملة من غير توزيع افتراضي.</small></div>${badge('تعديل وحفظ مباشر','gold')}</div><form id="entry-form"><div class="fields three"><div class="field"><label>الإداري</label><select id="entry-member" name="member_id" required><option value="">اختر الإداري</option>${fieldsMember()}</select></div><div class="field"><label>من يوم</label><input id="entry-start" name="start_on" type="date" min="${fDate(UI.data.week.starts)}" max="${fDate(UI.data.week.ends)}" value="${fDate(currentDay())}" required></div><div class="field"><label>إلى يوم</label><input id="entry-end" name="end_on" type="date" min="${fDate(UI.data.week.starts)}" max="${fDate(UI.data.week.ends)}" value="${fDate(currentDay())}" required></div></div><div class="fields four section-gap"><div class="field"><label>طريقة Tickets</label><select id="entry-mode" name="mode"><option value="counter">عداد اللعبة الأسبوعي</option><option value="direct">الزيادة للفترة</option></select></div><div class="field"><label>Tickets</label><input id="entry-tickets" name="tickets_counter" type="number" min="0" step="1" placeholder="الرقم في اللعبة" required></div><div class="field"><label>Flags التراكمية (اختياري)</label><input id="entry-flags" name="flags_counter" type="number" min="0" step="1" placeholder="الرقم في اللعبة"></div><div class="field"><label>Opening Flags (أول مرة فقط)</label><input id="entry-opening" name="opening_flags" type="number" min="0" step="1" placeholder="رصيد بداية الأسبوع"></div></div><div class="fields three section-gap"><div class="field"><label>TIME (ساعات عشرية)</label><input id="entry-hours" name="hours" type="number" min="0" max="168" step="0.25" placeholder="مثال: 1.5"></div><div class="field"><label>Rating من 5 (اختياري)</label><input id="entry-rate" name="rate" type="number" min="0" max="5" step="0.01" placeholder="مثال: 4.90"></div><div class="field"><label>ملاحظة (اختياري)</label><input id="entry-note" name="note" type="text" placeholder="ملاحظة على القراءة" maxlength="200"></div></div><div class="form-actions"><button class="btn btn-accent" type="submit">${I('save')} حفظ القراءة</button><button class="btn" type="button" data-action="clear-entry">تفريغ الخانات</button></div></form><div class="callout" style="margin-top:19px">${I('info')} <span>Tickets الأسبوعية بتتصفّر يوم الاثنين في اللعبة. Flags تراكمي، وTIME ساعات عشرية (1.5 = ساعة ونصف).</span></div></section>`}
function excelPanel(){return `<div class="card card-p"><div class="panel-header"><div><h2>استيراد إحصائيات Excel</h2><small>مراجعة الأسماء والأرقام قبل اعتماد الحفظ</small></div>${badge('XLSX فقط','gold')}</div><div class="upload-zone" id="upload-zone"><span class="upload-pict">${I('upload','icon-lg')}</span><h3>اختار ملف Excel</h3><p>اسحب الملف هنا أو اضغط لاختياره. مش هيتم حفظ أي حاجة قبل المراجعة.</p><span class="btn btn-accent">${I('upload')} اختيار الملف</span><input id="excel-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" aria-label="اختيار ملف Excel"></div><div id="excel-preview">${UI.excel?renderExcelPreview():''}</div></div>`}
function renderExcelPreview(){const x=UI.excel;if(!x)return '';const missing=x.matches.filter(m=>!m.match_id);return `<div class="section-gap">${info(`تاريخ الملف: <strong>${safe(x.parsed.date)}</strong> · ${x.parsed.rows.length} إداري · ${fmt(x.parsed.totals.tickets)} Tickets · ${fmt(x.parsed.totals.flags)} Flags`)}${x.parsed.warnings?.length?`<div class="callout red-callout section-gap">${I('alert')} <span>${x.parsed.warnings.map(w=>`${safe(w.name)}: ${safe(w.message)}`).join(' / ')}</span></div>`:''}<div class="table-scroll section-gap"><table class="table"><thead><tr><th>الاسم في Excel</th><th>المطابقة في CHICO</th><th>Tickets</th><th>Flags</th><th>Rating</th></tr></thead><tbody>${x.matches.map((m,i)=>{const r=x.parsed.rows[i],sel=UI.importMapping[m.source_row]||'';return `<tr><td>${safe(m.name)}</td><td><select data-map-row="${m.source_row}" style="min-width:170px"><option value="">اختار الإداري</option>${x.members.filter(e=>e.active&&e.rank!=='Responsible').map(e=>`<option value="id:${e.id}" ${sel==='id:'+e.id?'selected':''}>${safe(e.name)} · ${safe(e.rank)}</option>`).join('')}${['Administrator','Moderator','SN.Helper','Helper'].map(rank=>`<option value="new:${rank}" ${sel==='new:'+rank?'selected':''}>+ إضافة كـ ${rank}</option>`).join('')}</select></td><td class="numeric">${fmt(r.tickets)}</td><td class="numeric">${fmt(r.flags)}</td><td class="numeric">${Number(r.rate).toFixed(2)}</td></tr>`}).join('')}</tbody></table></div><div class="form-actions"><button class="btn btn-accent" data-action="excel-commit">${I('save')} اعتماد وحفظ Excel</button><button class="btn" data-action="excel-cancel">إلغاء المعاينة</button></div><p class="subtle" style="margin-top:11px">مش بنضيف أسماء جديدة تلقائيًا ولا بنغيّر رتبة حد من غير اختيارك.</p></div>`}
function server(){const t=UI.data.totals,seen=hasStats(),m=memberList();const vals=[['Helper',m.filter(x=>x.rank==='Helper')],['SN.Helper',m.filter(x=>x.rank==='SN.Helper')],['Moderator',m.filter(x=>x.rank==='Moderator')],['Administrator',m.filter(x=>x.rank==='Administrator')]];return head('CHICO ME / SERVER','إحصائيات السيرفر','ملخص الحسابات الفعلية من القراءات المسجلة فقط.',btn('تسجيل قراءة','new-entry','plus','btn btn-accent'))+metricCards()+`<div class="cols"><div class="stack">${card('Tickets حسب الرتبة','تذاكر الإداريين من كل فئة',seen?`<div class="rank-bars">${vals.map(([r,list])=>{const count=list.reduce((n,m)=>n+m.tickets,0);return `<div class="rank-row"><span class="rank-txt">${r}</span><div class="rank-meter"><span style="width:${t.tickets?Math.round(count/t.tickets*100):0}%"></span></div><b>${fmt(count)}</b></div>`}).join('')}</div>`:empty('chart','لا يوجد نشاط مسجل','الشارت هيظهر بعد تسجيل أول قراءة.'))}${card('توزيع Tickets على الإداريين','من سجل الأسبوع الحالي',seen?`<div class="table-scroll"><table class="table"><thead><tr><th>الإداري</th><th>الرتبة</th><th>Tickets</th><th>Flags</th><th>Rate</th></tr></thead><tbody>${m.filter(x=>x.entry_count).sort((a,b)=>b.tickets-a.tickets).map(x=>`<tr><td><strong>${safe(x.name)}</strong></td><td>${memberBadge(x)}</td><td class="numeric">${fmt(x.tickets)}</td><td>${flagChip(x)}</td><td>${ratingChip(x)}</td></tr>`).join('')}</tbody></table></div>`:empty('ticket','لا توجد تذاكر','أرقام السيرفر تعتمد على القراءات المحفوظة فقط.'))}</div><div class="stack">${card('حساب نسبة Flags','النسبة مستقلة عن Rating اللعبة',`<div class="card-p"><div style="display:flex;justify-content:center;gap:18px;align-items:baseline;direction:ltr;font:700 22px var(--en)"><span>${t.flags_observations?fmt(t.flags):'—'} <small>FLAGS</small></span><span style="color:var(--faint)">÷</span><span>${t.tickets_observations?fmt(t.tickets):'—'} <small>TICKETS</small></span></div><div style="text-align:center;color:var(--gold);font:700 40px var(--en);margin:16px 0">${t.flag_rate===null?'—':fmt(t.flag_rate)+'%'}</div>${info(t.flag_rate===null?'النسبة لن تظهر إلا بعد توفر قراءات Flags وTickets مكتملة.':'Flags الأسبوعية ÷ Tickets الأسبوعية × 100')}</div>`)}${card('Top 3 · Moderators','الترتيب للمودريتور فقط',`<div class="card-p">${rankingFor(m.filter(x=>x.rank==='Moderator'))}</div>`)}${card('Top 3 · Helpers','Helper و SN.Helper',`<div class="card-p">${rankingFor(m.filter(x=>['Helper','SN.Helper'].includes(x.rank)))}</div>`)}</div></div>`}
function previewReport(){const d=UI.reportPreview||UI.data;const t=d.totals;const dateFrom=d.period?.from||d.week.starts,dateTo=d.period?.to||d.week.ends;return `<div class="report-preview"><div class="overline">ONE STATE / CHICO ME</div><h2>CHICO GENERAL TEAM</h2><div class="subtle" style="color:#aab6c4">${safe(dateFrom)} — ${safe(dateTo)}</div><div class="preview-grid"><div><small>Tickets</small><b>${t.tickets_observations?fmt(t.tickets):'—'}</b></div><div><small>Flags</small><b>${t.flags_observations?fmt(t.flags):'—'}</b></div><div><small>Flag Rate</small><b>${t.flag_rate===null?'—':fmt(t.flag_rate)+'%'}</b></div></div><div class="report-foot">CHICO GENERAL TEAM • WEEKLY STATS</div></div>`}
function reports(){return head('REPORTS / CHICO','تقارير CHICO','معاينة وتصدير التقارير من بيانات اللعبة المسجلة فقط.',btn('تصدير PNG','download-report','download','btn btn-accent'))+`<div class="cols"><div class="stack">${card('معاينة التقرير','النسخة دي بدون أرقام تجريبية',`<div class="card-p"><div id="report-preview-wrap">${previewReport()}</div><div class="form-actions">${btn('حفظ في الأرشيف','archive-report','save','btn btn-accent')}${btn('تصدير CSV','export-csv','download')}</div></div>`)}${card('التقارير المحفوظة','تقدر تحذف أي تقرير محفوظ',UI.data.snapshots.length?`<div class="table-scroll"><table class="table"><thead><tr><th>التقرير</th><th>التاريخ</th><th>الإجراء</th></tr></thead><tbody>${UI.data.snapshots.map(x=>`<tr><td>#${x.id} · ${x.kind==='daily'?'يومي':'أسبوعي'}</td><td dir="ltr">${safe(x.created_at.slice(0,16))}</td><td><div class="row-actions"><button class="btn btn-small" data-preview-snapshot="${x.id}">${I('eye')} فتح</button><button class="btn btn-small btn-ghost" style="color:var(--red)" data-delete-snapshot="${x.id}">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('file','لا يوجد تقارير محفوظة','احفظ أول تقرير لما تبدأ تسجّل بيانات.'))}</div><div class="stack">${card('بيانات التقرير','كل تقرير بيتحسب من الأسبوع المحدد',`<div class="card-p"><div class="fields"><div class="field"><label>نوع التقرير</label><select id="report-type"><option value="weekly" ${UI.reportType==='weekly'?'selected':''}>أسبوعي</option><option value="daily" ${UI.reportType==='daily'?'selected':''}>فترة محددة</option></select></div><div class="field"><label>الأسبوع</label><input readonly value="${safe(UI.data.week.starts)} — ${safe(UI.data.week.ends)}"></div></div><div id="report-dates" class="fields section-gap" ${UI.reportType==='daily'?'':'hidden'}><div class="field"><label>من</label><input type="date" id="report-from" min="${safe(UI.data.week.starts)}" max="${safe(UI.data.week.ends)}" value="${safe(UI.data.week.starts)}"></div><div class="field"><label>إلى</label><input type="date" id="report-to" min="${safe(UI.data.week.starts)}" max="${safe(UI.data.week.ends)}" value="${safe(currentDay())}"></div></div><div class="callout section-gap">${I('info')} <span>Top 3 منفصل حسب الرتبة. Administrator يدخل في حساب السيرفر فقط، ومش في التوب.</span></div></div>`)}${card('جاهزية التقرير','مافيش أرقام متوقعة أو بيانات تلقائية',`<div class="card-p">${hasStats()?info('المعاينة مبنية على القراءات اللي اتسجلت بالفعل.'):empty('info','التقرير بدون بيانات','لما تبدأ تسجيل إحصائيات هتظهر الأرقام هنا.')}</div>`)}</div></div>`}
function week(){const w=UI.data.week,t=UI.data.totals;return head('GAME WEEK / CLOSING','إغلاق الأسبوع','الإغلاق يدوي بعد انتهاء أسبوع اللعبة، مش تلقائي.',btn('تسجيل قراءة','new-entry','ticket','btn btn-accent'))+`<div class="cols"><div class="stack">${card('الأسبوع الحالي','راجع الأرقام قبل الإغلاق',`<div class="card-p"><div class="weekline"><span>بداية الأسبوع</span><strong>${safe(w.starts)}</strong></div><div class="weekline"><span>نهاية الأسبوع</span><strong>${safe(w.ends)}</strong></div><div class="weekline"><span>Tickets الفريق</span><strong>${t.tickets_observations?fmt(t.team_tickets):'—'}</strong></div><div class="weekline"><span>Tickets الإدارة</span><strong>${t.tickets_observations?fmt(t.admin_tickets):'—'}</strong></div><div class="weekline"><span>Weekly Flags</span><strong>${t.flags_observations?fmt(t.flags):'—'}</strong></div>${!UI.data.reset_due?`<div class="callout section-gap">${I('clock')} <span>إغلاق الأسبوع متاح بعد نهايته، عند بداية الأسبوع الجديد يوم الاثنين.</span></div>`:''}<div class="form-actions"><button class="btn btn-accent" data-action="close-week" ${!UI.data.reset_due?'disabled':''}>${I('check')} إغلاق وفتح الأسبوع الجديد</button></div></div>`)}${card('سجل الأسابيع','الأسابيع السابقة المحفوظة',`<div class="card-p">${UI.data.weeks.map(w=>`<div class="weekline"><div><strong>${safe(w.starts)}</strong><small> → ${safe(w.ends)}</small></div>${badge(w.status==='open'?'مفتوح':'مغلق',w.status==='open'?'gold':'muted')}</div>`).join('')}</div>`)}</div><div class="stack">${card('قواعد أسبوع OneState','ثابتة في حسابات CHICO',`<div class="card-p"><div class="info-line">${I('ticket')} Tickets بتتصفّر كل يوم الاثنين</div><div class="info-line section-gap">${I('flag')} Flags تراكمية؛ بنتابع الفرق فقط</div><div class="info-line section-gap">${I('clock')} القراءة المتأخرة بتغطي مدة كاملة</div><div class="info-line section-gap">${I('shield')} تاريخ الترقية محفوظ</div></div>`)}</div></div>`}
function settings(){const members=memberList();return head('OWNER / SETTINGS','إعدادات CHICO','كل شيء قابل للتعديل أو المسح. الحذف نهائي بعد التأكيد.',btn('نسخة احتياطية','create-backup','download','btn btn-accent'))+`<div class="cols"><div class="stack">${card('الدخول إلى الموقع','كلمة سر واحدة فقط — من غير اسم مستخدم',`<div class="card-p"><div class="callout">${I('lock')} <span>الدخول والإدارة متاحان بكلمة سر المالك فقط. الحسابات الفردية مش مستخدمة.</span></div><form id="password-form" class="section-gap"><div class="fields"><div class="field"><label>كلمة السر الحالية</label><input name="old" type="password" required autocomplete="current-password"></div><div class="field"><label>كلمة السر الجديدة</label><input name="new" type="password" minlength="12" required autocomplete="new-password" placeholder="12 حرف على الأقل"></div></div><div class="form-actions"><button class="btn btn-accent" type="submit">${I('lock')} تغيير كلمة السر</button></div></form></div>`)}<section class="card danger-card"><div class="card-h"><div><h2 class="card-title">مسح البيانات</h2><p class="card-sub">بنحفظ نسخة احتياطية قبل المسح</p></div>${I('alert')}</div><div class="card-divider"></div><div class="card-p danger-zone"><div class="danger-action"><div><strong>مسح الإحصائيات فقط</strong><p>يمسح Tickets وFlags والتقييمات والسجلات والتقارير. يسيب الأسماء والرتب.</p></div>${btn('مسح الإحصائيات','reset-stats','trash','btn btn-danger btn-small')}</div><div class="danger-action"><div><strong>حذف كل بيانات الفريق</strong><p>يمسح الأسماء والرتب وكل إحصائيات اللعبة. تقدر تضيف الفريق من جديد.</p></div>${btn('حذف كل شيء','reset-all','trash','btn btn-danger btn-small')}</div></div></section></div><div class="stack">${card('حالة الفريق','أرقام الإدارة فقط',`<div class="card-p"><div class="weekline"><span>عدد الإداريين</span><strong>${members.length}</strong></div><div class="weekline"><span>القراءات المحفوظة</span><strong>${records().length}</strong></div><div class="weekline"><span>التقارير المحفوظة</span><strong>${UI.data.snapshots.length}</strong></div><div class="weekline"><span>الأسبوع المفتوح</span><strong>${safe(UI.data.week.starts)}</strong></div><div class="section-gap">${btn('فتح إدارة الأسماء والرتب','go-roster','users')}</div></div>`)}${card('النسخ الاحتياطية','تنزيل واستعادة بيانات CHICO',`<div class="card-p"><div id="backup-list">${empty('download','بيتم تحميل النسخ','')}</div><div class="form-actions">${btn('إنشاء وتنزيل نسخة','create-backup','download','btn btn-accent')}${btn('حذف كل النسخ الاحتياطية','delete-backups','trash','btn btn-danger btn-small')}</div></div>`)}${card('سجل التعديلات','آخر التغييرات اللي حصلت في CHICO',`<div class="card-p"><details><summary style="cursor:pointer;color:var(--gold);font-weight:800">عرض آخر التعديلات</summary><div class="section-gap">${UI.data.audit?.length?UI.data.audit.slice(0,20).map(r=>`<div class="weekline"><span>${safe(r.action)}</span><small dir="ltr">${safe(r.at.slice(0,16))}</small></div>`).join(''):empty('list','لا توجد تعديلات','')}</div></details></div>`)}</div></div>`}
function render(){if(!UI.data)return;nav();$('#breadcrumb').textContent=names[UI.page];$('#top-title').textContent=names[UI.page];const page={dashboard,roster,daily,server,reports,week,settings}[UI.page]||dashboard;$('#content').innerHTML=page();bindPage()}
// --------- Dialogs ---------
function modal(title,body,{wide=false}={}){$('#modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${safe(title)}"><header class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="إغلاق">${I('x')}</button></header><div class="modal-body">${body}</div></section></div>`}
function closeModal(){$('#modal-root').innerHTML=''}
function memberForm(m){const editing=Boolean(m);modal(editing?'تعديل بيانات الإداري':'إضافة إداري',`<form id="member-form"><input type="hidden" name="id" value="${m?.id||''}"><div class="fields"><div class="field"><label>اسم الإداري في OneState</label><input name="name" value="${safe(m?.name||'')}" placeholder="اسم الإداري" required minlength="2" maxlength="48" autofocus></div><div class="field"><label>الرتبة</label><select name="rank">${ranks.map(r=>`<option value="${r}" ${m?.rank===r?'selected':''}>${r}</option>`).join('')}</select></div></div>${editing?`<div class="fields"><div class="field"><label>ترتيب الظهور</label><input type="number" name="display_order" min="0" max="100000" value="${Number(m.display_order??10000)}"></div><div></div></div><div class="toggle-row"><div><strong>نشط في الفريق</strong><p>إلغاء التفعيل يخفي الإداري من تقارير النشاط.</p></div><input class="switch" type="checkbox" name="active" ${m.active?'checked':''}></div><div class="toggle-row"><div><strong>يظهر في تقارير الفريق</strong><p>حسابات السيرفر تعتمد على القراءات الفعلية.</p></div><input class="switch" type="checkbox" name="reporting" ${m.reporting?'checked':''}></div>`:''}<div class="form-actions"><button class="btn btn-accent" type="submit">${I('save')} ${editing?'حفظ التعديلات':'إضافة الإداري'}</button><button class="btn" type="button" data-action="close-modal">إلغاء</button>${editing?`<button type="button" class="btn btn-danger" data-delete-member="${m.id}">${I('trash')} حذف الإداري</button>`:''}</div></form>`)}
function memberDetail(id){const m=memberList().find(x=>x.id===Number(id));if(!m)return;const shifts=m.shift_history||[],rates=m.daily_ratings||[],rr=m.data||[];modal(`ملف الإداري · ${safe(m.name)}`,`<div style="display:flex;gap:15px;align-items:center;margin-bottom:24px"><div class="avatar" style="width:65px;height:65px;font-size:22px">${safe(m.name.slice(0,2).toUpperCase())}</div><div><strong style="font-size:19px">${safe(m.name)}</strong><div>${memberBadge(m)} ${m.active?badge('نشط','good'):badge('غير نشط','muted')}</div></div></div><div class="stats-grid" style="grid-template-columns:repeat(2,1fr)">${stat('Tickets',fmt(m.tickets),m.entry_count>0,'هذا الأسبوع','ticket')}${stat('Flags',fmt(m.flags),m.entry_count>0,'هذا الأسبوع','flag')}${stat('Rate',m.rate===null?'—':Number(m.rate).toFixed(2),m.rate!==null,'من 5','star')}${stat('TIME',m.hours===null?'—':fmt(m.hours)+'h',m.hours!==null,'ساعات عشرية','clock')}</div><div class="form-actions">${btn('تعديل الإداري','edit-member-'+m.id,'edit','btn btn-accent')}${btn('إضافة قراءة','read-member-'+m.id,'plus')}${btn('المناوبة','shift-member-'+m.id,'clock')}${btn('Opening Flags','opening-member-'+m.id,'flag')}${btn('حذف الإداري','delete-member-'+m.id,'trash','btn btn-danger')}</div><div class="section-gap">${card('القراءات المسجلة','حذف كل قراءة متاح من صفحة الإحصائيات',rr.length?`<div class="table-scroll"><table class="table"><thead><tr><th>الفترة</th><th>Tickets</th><th>Flags</th><th>الإجراء</th></tr></thead><tbody>${rr.map(r=>`<tr><td dir="ltr">${safe(r.start_on)} → ${safe(r.end_on)}</td><td>${fmt(r.tickets)}</td><td>${r.flags===null?'—':fmt(r.flags)}</td><td><div class="row-actions"><button class="btn btn-small" data-edit-entry="${r.id}">${I('edit')}</button><button class="btn btn-small btn-ghost" style="color:var(--red)" data-delete-entry="${r.id}">${I('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('ticket','لا توجد قراءات',''))}</div><div class="section-gap">${info('Opening Flags: '+(m.opening_flags===null?'غير مسجل':fmt(m.opening_flags)))} ${btn('تعديل رصيد البداية','opening-member-'+m.id,'edit','btn btn-small')}</div>${shifts.length?`<div class="section-gap">${card('سجل المناوبات','',`<div class="card-p">${shifts.map(s=>`<div class="weekline"><span>${safe(s.shift)} <small>${safe(s.effective_on)}</small></span>${btn('حذف','none','trash','btn btn-small btn-danger').replace('data-action="none"',`data-delete-shift="${s.id}"`)}</div>`).join('')}</div>`)}</div>`:''}${rates.length?`<div class="section-gap">${card('التقييمات','',`<div class="card-p">${rates.map(r=>`<div class="weekline"><span>${safe(r.evaluation_date)} — ${Number(r.rate).toFixed(2)}</span>${btn('حذف','none','trash','btn btn-small btn-danger').replace('data-action="none"',`data-delete-rating="${r.id}"`)}</div>`).join('')}</div>`)}</div>`:''}`,{wide:true})}
function alertDelete(title,description,onConfirm){modal(title,`<div class="callout red-callout">${I('alert')} <span>${description}</span></div><div class="danger-confirm"><strong>تأكيد الحذف</strong><p>العملية مش هتتراجع من الموقع، لكن فيه نسخة احتياطية قبل الحذف.</p><form id="confirm-form"><input id="confirm-word" type="text" placeholder="اكتب DELETE للتأكيد" autocomplete="off" required><div class="form-actions"><button class="btn btn-danger" type="submit">${I('trash')} حذف نهائي</button><button type="button" class="btn" data-action="close-modal">إلغاء</button></div></form></div>`);$('#confirm-form').onsubmit=async e=>{e.preventDefault();if($('#confirm-word').value.trim()!=='DELETE')return toast('اكتب DELETE للتأكيد',true);await onConfirm()}}
function resetModal(scope){const all=scope==='all',phrase=all?'DELETE ALL':'RESET STATS';modal(all?'حذف كل بيانات الفريق':'مسح الإحصائيات',`<div class="callout red-callout">${I('alert')}<span>${all?'هتحذف كل الأسماء والرتب والقراءات والتقارير، وهيفضل الموقع فاضي لحد ما تضيف أسماء جديدة.':'هيفضل اسم كل إداري ورتبته وترتيبه، وتتمسح إحصائيات الأسبوع والسجلات والتقييمات والتقارير.'}</span></div><form id="reset-form" class="section-gap"><div class="field"><label>اكتب <b dir="ltr">${phrase}</b> للتأكيد</label><input name="confirmation" required autocomplete="off" placeholder="${phrase}"></div><div class="field section-gap"><label>كلمة سر الموقع</label><input type="password" name="password" required autocomplete="current-password" placeholder="أدخل كلمة السر"></div><div class="form-actions"><button class="btn btn-danger" type="submit">${I('trash')} ${all?'حذف كل شيء':'مسح الإحصائيات'}</button><button type="button" class="btn" data-action="close-modal">إلغاء</button></div></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('confirmation')!==phrase)return toast('اكتب عبارة التأكيد بشكل صحيح',true);try{const r=await API('data/reset',{scope,confirmation:phrase,password:f.get('password')});closeModal();UI.selected.clear();UI.excel=null;await refresh(true);go(all?'roster':'dashboard');toast('تم المسح. اتعملت نسخة احتياطية قبل العملية.')}catch(err){toast(err.message,true)}}}
function entryModal(record=null,memberID=null){const m=record?memberList().find(x=>x.id===record.member_id):memberList().find(x=>x.id===Number(memberID));const r=record;modal(r?'تعديل قراءة اللعبة':'تسجيل قراءة جديدة',`<form id="modal-entry-form"><div class="fields"><div class="field"><label>الإداري</label><select name="member_id" required ${r?'disabled':''}><option value="">اختار الإداري</option>${memberList().filter(x=>x.rank!=='Responsible').map(x=>`<option value="${x.id}" ${m?.id===x.id?'selected':''}>${safe(x.name)} · ${safe(x.rank)}</option>`).join('')}</select></div><div class="field"><label>طريقة Tickets</label><select name="mode"><option value="counter" ${r?.mode==='counter'?'selected':''}>عداد اللعبة الأسبوعي</option><option value="direct" ${r?.mode==='direct'?'selected':''}>زيادة الفترة</option></select></div></div><div class="fields"><div class="field"><label>من يوم</label><input type="date" name="start_on" value="${safe(r?.start_on||currentDay())}" min="${safe(UI.data.week.starts)}" max="${safe(UI.data.week.ends)}" ${r?'readonly':''} required></div><div class="field"><label>إلى يوم</label><input type="date" name="end_on" value="${safe(r?.end_on||currentDay())}" min="${safe(UI.data.week.starts)}" max="${safe(UI.data.week.ends)}" ${r?'readonly':''} required></div></div><div class="fields"><div class="field"><label>Tickets / Counter</label><input type="number" name="tickets_value" min="0" step="1" value="${r?r.mode==='counter'?r.tickets_counter:r.tickets:''}" required></div><div class="field"><label>Flags التراكمية</label><input type="number" name="flags_counter" min="0" step="1" value="${r?.flags_counter??''}" placeholder="اختياري"></div></div><div class="fields"><div class="field"><label>Opening Flags (لو أول مرة)</label><input type="number" name="opening_flags" min="0" step="1" value="${m?.opening_flags??''}"></div><div class="field"><label>TIME بالساعات العشرية</label><input type="number" name="hours" step="0.25" min="0" max="168" value="${r?.hours??''}" placeholder="مثال: 2.5"></div></div><div class="field"><label>Rating من 5 (اختياري)</label><input type="number" name="rate" step="0.01" min="0" max="5" value="${r?.rate??''}"></div><div class="field"><label>ملاحظة</label><textarea name="note" maxlength="200">${safe(r?.note||'')}</textarea></div><div class="form-actions"><button type="submit" class="btn btn-accent">${I('save')} حفظ القراءة</button><button type="button" class="btn" data-action="close-modal">إلغاء</button>${r?`<button class="btn btn-danger" type="button" data-delete-entry="${r.id}">${I('trash')} حذف القراءة</button>`:''}</div></form>`);$('#modal-entry-form').onsubmit=async e=>{e.preventDefault();await saveEntryForm(e.target,r)}}
async function saveEntryForm(form,record){const f=new FormData(form),mid=record?.member_id||Number(f.get('member_id')),start=f.get('start_on'),end=f.get('end_on'),mode=f.get('mode'),v=f.get('tickets_value');const row={member_id:mid,start_on:start,end_on:end,mode,expected:record?.revision??null,flags_counter:f.get('flags_counter')||null,opening_flags:f.get('opening_flags')||null,hours:f.get('hours')||null,rate:f.get('rate')||null,note:f.get('note')||''};if(mode==='direct')row.tickets=v;else row.tickets_counter=v;try{await API('entry',{from:start,to:end,rows:[row]});closeModal();await refresh(true);toast('اتحفظت قراءة اللعبة')}catch(err){toast(err.message,true)}}
function ratingModal(id){const r=ratingRecords().find(x=>x.id===Number(id));if(!r)return;modal('تعديل Rating · '+safe(r.name),`<form id="rating-form"><div class="field"><label>تاريخ التقييم</label><input type="date" name="evaluation_date" value="${safe(r.evaluation_date)}" readonly></div><div class="field section-gap"><label>Rating من 5</label><input type="number" min="0" max="5" step="0.01" name="rate" value="${r.rate}" required></div><div class="form-actions"><button type="submit" class="btn btn-accent">${I('save')} حفظ التقييم</button><button type="button" class="btn btn-danger" data-delete-rating="${r.id}">${I('trash')} حذف التقييم</button></div></form>`);$('#rating-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await API('ratings',{evaluation_date:r.evaluation_date,rows:[{member_id:r.member_id,rate:f.get('rate'),expected:r.revision}]});closeModal();await refresh(true);toast('اتعدّل Rating اللعبة')}catch(err){toast(err.message,true)}}}
function openingModal(mid){const m=memberList().find(x=>x.id===Number(mid));if(!m)return;modal('تعديل Opening Flags · '+safe(m.name),`<form id="opening-form"><div class="field"><label>رصيد Flags بداية الأسبوع</label><input type="number" min="0" step="1" name="flags_base" value="${m.opening_flags??''}" required></div><div class="field section-gap"><label>سبب التعديل</label><input name="reason" placeholder="مثال: تصحيح الرصيد من اللعبة" required maxlength="200"></div><div class="form-actions"><button class="btn btn-accent" type="submit">${I('save')} حفظ الرصيد</button>${m.opening_flags!==null?`<button class="btn btn-danger" type="button" data-action="delete-opening-${m.id}">${I('trash')} حذف</button>`:''}</div></form>`);$('#opening-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await API('openings',{rows:[{member_id:m.id,flags_base:f.get('flags_base')}],reason:f.get('reason')});closeModal();await refresh(true);toast('اتعدّل رصيد Flags')}catch(err){toast(err.message,true)}}}
function shiftModal(mid){const m=memberList().find(x=>x.id===mid);if(!m)return;modal('مناوبة '+safe(m.name),`<form id="shift-form"><div class="fields"><div class="field"><label>المناوبة الثابتة</label><input name="shift" required placeholder="مثال: 20:00–22:00" value="${safe(m.shift||'')}"></div><div class="field"><label>تاريخ بداية المناوبة</label><input type="date" name="effective_on" value="${safe(UI.data.today)}" required></div></div><div class="form-actions"><button type="submit" class="btn btn-accent">${I('save')} حفظ المناوبة</button></div></form>`);$('#shift-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await API('shift',{member_id:mid,shift:f.get('shift'),effective_on:f.get('effective_on')});closeModal();await refresh(true);toast('اتحفظت المناوبة')}catch(err){toast(err.message,true)}}}
function closeWeekModal(){modal('إغلاق أسبوع اللعبة',`<div class="callout">${I('alert')} <span>راجع أرقام القائد قبل إغلاق الأسبوع وفتح الأسبوع الجديد.</span></div><form id="week-form" class="section-gap"><div class="fields three"><div class="field"><label>Tickets الفريق (حسب تقرير القائد)</label><input name="team_tickets" type="number" min="0" step="1"></div><div class="field"><label>Tickets الإدارة</label><input name="admin_tickets" type="number" min="0" step="1"></div><div class="field"><label>Weekly Flags</label><input name="flags" type="number" min="0" step="1"></div></div><div class="field"><label>ملاحظة</label><input name="note" placeholder="اختياري"></div><div class="toggle-row"><span>أوافق على الإغلاق حتى لو فيه فروق مع تقرير القائد</span><input type="checkbox" class="switch" name="acknowledge_differences"></div><div class="form-actions"><button class="btn btn-accent" type="submit">${I('check')} تأكيد إغلاق الأسبوع</button><button class="btn" type="button" data-action="close-modal">إلغاء</button></div></form>`);$('#week-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const leader={note:f.get('note'),acknowledge_differences:f.has('acknowledge_differences')};for(const k of ['team_tickets','admin_tickets','flags'])if(f.get(k)!=='')leader[k]=f.get(k);try{await API('close',{leader,confirmed:true});closeModal();await refresh(true);toast('اتقفل الأسبوع واتفتح الأسبوع الجديد')}catch(err){toast(err.message,true)}}}
async function loadBackups(){const node=$('#backup-list');if(!node)return;try{const d=await API('owner/diagnostics');UI.backups=d.backups||[];node.innerHTML=UI.backups.length?UI.backups.slice(0,12).map(x=>`<div class="weekline"><div><strong style="font-size:11px;direction:ltr;display:inline-block">${safe(x.name)}</strong><small style="display:block">${safe(String(x.modified||'').slice(0,16))}</small></div><div class="row-actions">${x.name.endsWith('.json')?`<button class="btn btn-small" data-download-backup="${safe(x.name)}" title="تنزيل">${I('download')}</button>`:''}<button class="btn btn-small btn-danger" data-restore-backup="${safe(x.name)}" title="استعادة">${I('refresh')}</button><button class="btn btn-small btn-ghost" data-delete-backup="${safe(x.name)}" title="حذف النسخة">${I('trash')}</button></div></div>`).join(''):empty('download','لا توجد نسخ محفوظة','أنشئ نسخة احتياطية للحفظ والاستعادة.')}catch(e){node.innerHTML=empty('alert','فشل تحميل النسخ',safe(e.message))}}
function backupDeleteModal(filename=null){const all=!filename,phrase=all?'DELETE BACKUPS':'DELETE BACKUP';modal(all?'حذف جميع النسخ الاحتياطية':'حذف نسخة احتياطية',`<div class="callout red-callout">${I('alert')} <span>${all?'هتحذف كل النسخ الاحتياطية المخزنة داخل نظام CHICO، ولن تقدر ترجعها من الموقع.':'هتحذف النسخة '+safe(filename)+' نهائيًا.'}</span></div><form id="backup-delete-form" class="section-gap"><div class="field"><label>اكتب ${phrase} للتأكيد</label><input name="confirmation" placeholder="${phrase}" autocomplete="off" required></div><div class="field section-gap"><label>كلمة سر الموقع</label><input type="password" name="password" required></div><div class="form-actions"><button class="btn btn-danger" type="submit">${I('trash')} حذف نهائي</button><button class="btn" type="button" data-action="close-modal">إلغاء</button></div></form>`);$('#backup-delete-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('confirmation')!==phrase)return toast('اكتب عبارة التأكيد',true);try{await API('owner/backup/delete',{filename,confirmation:phrase,password:f.get('password')});closeModal();await loadBackups();toast('اتحذفت النسخ المطلوبة نهائيًا')}catch(err){toast(err.message,true)}}}
function restoreModal(filename){modal('استعادة نسخة احتياطية',`<div class="callout red-callout">${I('alert')}<span>استعادة <strong>${safe(filename)}</strong> هتستبدل البيانات الحالية بالكامل. اتأكد إن دي النسخة المطلوبة.</span></div><form id="restore-form" class="section-gap"><div class="field"><label>اكتب RESTORE للتأكيد</label><input name="confirmation" required placeholder="RESTORE" autocomplete="off"></div><div class="field section-gap"><label>كلمة سر الموقع</label><input type="password" name="password" required autocomplete="current-password"></div><div class="form-actions"><button class="btn btn-danger" type="submit">${I('refresh')} استعادة النسخة</button><button class="btn" type="button" data-action="close-modal">إلغاء</button></div></form>`);$('#restore-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('confirmation')!=='RESTORE')return toast('اكتب RESTORE للتأكيد',true);try{await API('owner/restore',{filename,owner_password:f.get('password'),confirmation:'RESTORE'});closeModal();saveToken('');showLogin();toast('تمت الاستعادة. ادخل بكلمة السر من جديد.')}catch(err){toast(err.message,true)}}}
// ---- Data operations -----
async function destroy(kind,id){const operations={member:['members/delete',{id,confirm:'DELETE'}],entry:['records/delete',{kind:'entry',id,confirm:'DELETE'}],rating:['records/delete',{kind:'rating',id,confirm:'DELETE'}],shift:['records/delete',{kind:'shift',id,confirm:'DELETE'}],snapshot:['records/delete',{kind:'snapshot',id,confirm:'DELETE'}],opening:['records/delete',{kind:'opening',id,confirm:'DELETE'}]};const [endpoint,payload]=operations[kind];try{await API(endpoint,payload);closeModal();UI.selected.delete(id);await refresh(true);toast('تم الحذف من CHICO')}catch(err){toast(err.message,true)}}
async function commitExcel(){if(!UI.excel)return;const x=UI.excel,matchKeys=x.matches.map(m=>String(m.source_row));if(matchKeys.some(k=>!UI.importMapping[k]))return toast('لازم تحدد المطابقة لكل إداري',true);const vals=Object.values(UI.importMapping);const chosen=vals.filter(v=>v.startsWith('id:'));if(new Set(chosen).size!==chosen.length)return toast('فيه اسم مكرر في مطابقة Excel',true);try{const res=await API('import/commit',{ticket:x.ticket,mapping:UI.importMapping,reset:false});UI.excel=null;UI.importMapping={};UI.dailyTab='manual';await refresh(true);toast('اتحفظ '+res.saved+' سجل من Excel')}catch(err){toast(err.message,true)}}
async function parseExcel(file){if(!file)return;if(!file.name.toLowerCase().endsWith('.xlsx'))return toast('اختار ملف XLSX',true);if(file.size>2_000_000)return toast('الملف أكبر من 2MB',true);try{const buf=await file.arrayBuffer();const bytes=new Uint8Array(buf);let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const data=btoa(binary);const result=await API('import/preview',{data});UI.excel=result;UI.importMapping={};result.matches.forEach(m=>{if(m.match_id)UI.importMapping[m.source_row]='id:'+m.match_id});$('#excel-preview').innerHTML=renderExcelPreview();toast('اتقرا ملف Excel. راجع الأسماء قبل الحفظ.')}catch(err){toast(err.message,true)}}
async function loadReportPreview(){if(UI.reportType!=='daily'){UI.reportPreview=null;const e=$('#report-preview-wrap');if(e)e.innerHTML=previewReport();return}const a=$('#report-from')?.value,b=$('#report-to')?.value;if(!a||!b||a>b)return toast('راجع تاريخ التقرير',true);try{UI.reportPreview=await API('report?from='+encodeURIComponent(a)+'&to='+encodeURIComponent(b));const el=$('#report-preview-wrap');if(el)el.innerHTML=previewReport()}catch(err){toast(err.message,true)}}
async function downloadReport(){const d=UI.reportPreview||UI.data;if(!(d.totals?.tickets_observations||d.totals?.rate_observations))return toast('لا توجد إحصائيات لعمل صورة تقرير',true);const c=document.createElement('canvas');c.width=1400;c.height=930;const ctx=c.getContext('2d');ctx.fillStyle='#101720';ctx.fillRect(0,0,1400,930);const grd=ctx.createLinearGradient(0,0,1400,930);grd.addColorStop(0,'#182533');grd.addColorStop(.7,'#151e28');grd.addColorStop(1,'#392621');ctx.fillStyle=grd;ctx.fillRect(30,30,1340,870);ctx.strokeStyle='#a97950';ctx.lineWidth=3;ctx.strokeRect(42,42,1316,846);ctx.direction='ltr';ctx.textAlign='left';ctx.fillStyle='#e5b26f';ctx.font='bold 38px Arial';ctx.fillText('CHICO GENERAL TEAM',106,150);ctx.fillStyle='#9dadbe';ctx.font='bold 22px Arial';ctx.fillText('ONESTATE RP  /  CHICO ME  /  WEEKLY REPORT',108,190);ctx.fillStyle='#d9e3ea';ctx.font='bold 25px Arial';ctx.fillText(`${d.period?.from||d.week.starts}  —  ${d.period?.to||d.week.ends}`,108,251);const t=d.totals,vals=[['TICKETS',t.tickets_observations?fmt(t.tickets):'—'],['WEEKLY FLAGS',t.flags_observations?fmt(t.flags):'—'],['FLAG RATE',t.flag_rate===null?'—':fmt(t.flag_rate)+'%']];vals.forEach(([lab,v],i)=>{const x=107+i*398;ctx.fillStyle='#263440';ctx.fillRect(x,311,365,170);ctx.fillStyle='#bac7d1';ctx.font='bold 22px Arial';ctx.fillText(lab,x+20,357);ctx.fillStyle='#faf0dc';ctx.font='bold 67px Arial';ctx.fillText(v,x+20,438)});let y=545;ctx.fillStyle='#e5b26f';ctx.font='bold 25px Arial';ctx.fillText('TOP HELPERS',106,y);const helpers=d.members.filter(m=>m.active&&m.entry_count&&['Helper','SN.Helper'].includes(m.rank)).sort((a,b)=>b.tickets-a.tickets).slice(0,3);ctx.font='bold 25px Arial';helpers.forEach((m,i)=>{ctx.fillStyle='#e4e9ee';ctx.fillText(`${i+1}.  ${m.name}    ${fmt(m.tickets)} Tickets`,110,y+55+i*42)});ctx.fillStyle='#e5b26f';ctx.fillText('TOP MODERATORS',760,y);const mods=d.members.filter(m=>m.active&&m.entry_count&&m.rank==='Moderator').sort((a,b)=>b.tickets-a.tickets).slice(0,3);ctx.font='bold 25px Arial';mods.forEach((m,i)=>{ctx.fillStyle='#e4e9ee';ctx.fillText(`${i+1}.  ${m.name}    ${fmt(m.tickets)} Tickets`,762,y+55+i*42)});ctx.fillStyle='#b6c2cc';ctx.font='19px Arial';ctx.fillText('Only recorded game data.  •  CHICO GENERAL TEAM',106,843);const logo=new Image();logo.onload=()=>{ctx.drawImage(logo,1200,90,96,96);save()};logo.onerror=save;logo.src='/assets/chico-wolf-safe-192.png';function save(){c.toBlob(blob=>{if(!blob)return toast('فشل تصدير الصورة',true);const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='CHICO_'+UI.reportType+'_'+(d.period?.from||d.week.starts)+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),2500)},'image/png')}}
function exportCsv(){const d=UI.reportPreview||UI.data;const lines=[['Rank','Name','Tickets','Weekly Flags','Rating','Hours'],...d.members.map(m=>[m.rank,m.name,m.entry_count?m.tickets:'',m.entry_count?m.flags:'',m.rate??'',m.hours??''])];const raw='\ufeff'+lines.map(row=>row.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([raw],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='CHICO_'+(d.period?.from||d.week.starts)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1300)}
async function createBackup(){try{const b=await API('owner/backup',{});if(b.filename.endsWith('.json')){const res=await fetch('/api/owner/backup/download?filename='+encodeURIComponent(b.filename),{headers:{Authorization:'Bearer '+UI.token}});if(!res.ok)throw Error('فشل تنزيل النسخة الاحتياطية');const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;a.download=b.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('اتعملت نسخة احتياطية واتنزلت عندك')}else toast('اتحفظت نسخة احتياطية محلية: '+b.filename)}catch(err){toast(err.message,true)}}
// Page-local controls
function bindPage(){if(UI.page==='roster'){$('#roster-search').oninput=e=>{UI.query=e.target.value;$('#roster-table').innerHTML=rosterTable()};$('#roster-rank').onchange=e=>{UI.rank=e.target.value;$('#roster-table').innerHTML=rosterTable()};$('#roster-active').onchange=e=>{UI.active=e.target.value;$('#roster-table').innerHTML=rosterTable()}}
if(UI.page==='daily'){$('#entry-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),mid=Number(f.get('member_id'));if(!mid)return toast('اختار الإداري',true);const row={member_id:mid,start_on:f.get('start_on'),end_on:f.get('end_on'),mode:f.get('mode'),flags_counter:f.get('flags_counter')||null,opening_flags:f.get('opening_flags')||null,hours:f.get('hours')||null,rate:f.get('rate')||null,note:f.get('note')||''};if(row.mode==='counter')row.tickets_counter=f.get('tickets_counter');else row.tickets=f.get('tickets_counter');try{await API('entry',{from:row.start_on,to:row.end_on,rows:[row]});await refresh(true);toast('اتحفظت القراءة والتقييم')}catch(err){toast(err.message,true)}})}
if(UI.page==='reports'){$('#report-type')?.addEventListener('change',e=>{UI.reportType=e.target.value;$('#report-dates').hidden=e.target.value!=='daily';loadReportPreview()});$('#report-from')?.addEventListener('change',loadReportPreview);$('#report-to')?.addEventListener('change',loadReportPreview)}
if(UI.page==='settings'){loadBackups();$('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await API('password/change',{old:f.get('old'),new:f.get('new')});toast('اتغيرت كلمة السر. سجل الدخول بالكلمة الجديدة.');saveToken('');showLogin()}catch(err){toast(err.message,true)}})}}
// Global event delegation ensures modals, tables and mobile nav always work.
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){UI.dailyTab=b.dataset.tab;render();return}const route=b.dataset.route;if(route){go(route);return}const action=b.dataset.action;if(action){switch(action){case 'refresh':case 'refresh-btn':await refresh();break;case 'close-modal':closeModal();break;case 'new-entry':go('daily');setTimeout(()=>$('#entry-member')?.focus(),30);break;case 'go-roster':go('roster');break;case 'go-excel':UI.dailyTab='excel';go('daily');break;case 'add-member':memberForm(null);break;case 'bulk-delete':{const selected=[...UI.selected];if(!selected.length){toast('اختار الإداريين اللي عايز تحذفهم',true);break}alertDelete('حذف الإداريين المحددين',`هتحذف ${selected.length} إداري وكل سجلاتهم والتقارير المؤرشفة.`,async()=>{try{for(const id of selected)await API('members/delete',{id,confirm:'DELETE'});UI.selected.clear();closeModal();await refresh(true);toast('اتحذف الإداريون المحددون')}catch(err){toast(err.message,true)}});break}case 'excel-commit':await commitExcel();break;case 'excel-cancel':UI.excel=null;UI.importMapping={};render();break;case 'clear-entry':$('#entry-form')?.reset();break;case 'download-report':await downloadReport();break;case 'export-csv':exportCsv();break;case 'archive-report':try{if(!hasStats()){toast('لا توجد إحصائيات لحفظ تقرير',true);break}const period=UI.reportType==='daily';const r=await API('snapshot',{kind:UI.reportType,...(period?{from:$('#report-from').value,to:$('#report-to').value}:{})});await refresh(true);toast('اتحفظ التقرير #'+r.id)}catch(err){toast(err.message,true)}break;case 'create-backup':await createBackup();break;case 'delete-backups':backupDeleteModal();break;case 'reset-stats':resetModal('statistics');break;case 'reset-all':resetModal('all');break;case 'close-week':closeWeekModal();break;default:if(action.startsWith('edit-member-'))memberForm(memberList().find(m=>m.id===Number(action.split('-').at(-1))));else if(action.startsWith('read-member-'))entryModal(null,Number(action.split('-').at(-1)));else if(action.startsWith('shift-member-'))shiftModal(Number(action.split('-').at(-1)));else if(action.startsWith('opening-member-'))openingModal(Number(action.split('-').at(-1)));else if(action.startsWith('delete-member-')){const id=Number(action.split('-').at(-1));alertDelete('حذف الإداري',`سيتم حذف ${safe(memberList().find(m=>m.id===id)?.name)} وكل إحصائياته المحفوظة.`,()=>destroy('member',id))}else if(action.startsWith('delete-opening-')){const id=Number(action.split('-').at(-1));alertDelete('حذف Opening Flags','سيتم حذف رصيد بداية الأسبوع للإداري.',()=>destroy('opening',id))}}return}
const attr=(name)=>b.dataset[name];if(attr('member')){memberDetail(attr('member'));return}if(attr('editMember')){memberForm(memberList().find(m=>m.id===Number(attr('editMember'))));return}if(attr('deleteMember')){const id=Number(attr('deleteMember'));alertDelete('حذف إداري',`سيتم حذف ${safe(memberList().find(m=>m.id===id)?.name||'الإداري')} وكل سجلاته المحفوظة.`,()=>destroy('member',id));return}if(attr('editRating')){ratingModal(attr('editRating'));return}if(attr('editEntry')){const r=records().find(x=>x.id===Number(attr('editEntry')));if(r)entryModal(r);return}for(const [name,kind] of [['deleteEntry','entry'],['deleteRating','rating'],['deleteShift','shift'],['deleteSnapshot','snapshot']])if(attr(name)){const id=Number(attr(name));alertDelete('حذف السجل','سيتم حذف السجل المحدد نهائيًا بعد أخذ نسخة احتياطية.',()=>destroy(kind,id));return}if(attr('restoreBackup')){restoreModal(attr('restoreBackup'));return}if(attr('deleteBackup')){backupDeleteModal(attr('deleteBackup'));return}if(attr('downloadBackup')){try{const filename=attr('downloadBackup');const res=await fetch('/api/owner/backup/download?filename='+encodeURIComponent(filename),{headers:{Authorization:'Bearer '+UI.token}});if(!res.ok)throw Error('تعذّر تنزيل النسخة');const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}catch(err){toast(err.message,true)}return}if(attr('previewSnapshot')){try{const r=await API('snapshot?id='+attr('previewSnapshot'));const s=JSON.parse(r.snapshot.payload);modal('تقرير محفوظ #'+r.snapshot.id,`<div class="info-kpis"><span>Tickets <b>${fmt(s.totals?.tickets)}</b></span><span>Flags <b>${fmt(s.totals?.flags)}</b></span><span>Flag Rate <b>${s.totals?.flag_rate??'—'}</b></span></div><div class="section-gap">${info('أرشيف أسبوع '+safe(s.week?.starts||'')+' إلى '+safe(s.week?.ends||''))}</div>`)}catch(err){toast(err.message,true)}}});
document.addEventListener('change',e=>{const b=e.target;if(b.matches('[data-select-member]')){const id=Number(b.dataset.selectMember);if(b.checked)UI.selected.add(id);else UI.selected.delete(id)}if(b.id==='select-all'){for(const m of filteredMembers())b.checked?UI.selected.add(m.id):UI.selected.delete(m.id);$('#roster-table').innerHTML=rosterTable()}if(b.matches('[data-map-row]'))UI.importMapping[b.dataset.mapRow]=b.value;if(b.id==='excel-file'){parseExcel(b.files[0])}if(b.id==='entry-mode'){const field=$('#entry-tickets');if(field){field.placeholder=b.value==='counter'?'الرقم الحالي في اللعبة':'الزيادة للفترة'}}});
document.addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
document.addEventListener('submit',async e=>{if(!e.target.matches('#member-form'))return;e.preventDefault();const f=new FormData(e.target),id=Number(f.get('id'));try{if(id){await API('members/manage',{id,name:f.get('name'),rank:f.get('rank'),display_order:Number(f.get('display_order')),active:f.has('active'),reporting:f.has('reporting')})}else await API('members/add',{name:f.get('name'),rank:f.get('rank')});closeModal();await refresh(true);toast(id?'اتعدّلت بيانات الإداري':'اتضاف الإداري للفريق')}catch(err){toast(err.message,true)}});
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('.login-submit');btn.disabled=true;$('#login-error').hidden=true;try{const resp=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#password').value})});const out=await resp.json();if(!resp.ok||out.role!=='owner')throw Error(out.error||'كلمة السر غير صحيحة');saveToken(out.token);showApp()}catch(err){const field=$('#login-error');field.hidden=false;field.textContent=err.message}finally{btn.disabled=false}});
$('#peek-password').innerHTML=I('eye');$('#peek-password').onclick=()=>{$('#password').type=$('#password').type==='password'?'text':'password'};
$('#theme-btn').onclick=()=>{UI.theme=UI.theme==='dark'?'light':'dark';document.body.dataset.theme=UI.theme;try{localStorage.setItem('chico_theme',UI.theme)}catch{};setChromeIcons()};
$('#refresh-btn').onclick=()=>refresh();
$('#logout-btn').onclick=async()=>{try{await API('logout',{})}catch{}saveToken('');showLogin()};
$('#menu-btn').onclick=()=>{$('#sidebar').classList.toggle('open');$('#mobile-scrim').classList.toggle('open')};
$('#mobile-scrim').onclick=closeSidebar;
function setChromeIcons(){$('#theme-btn').innerHTML=I(UI.theme==='dark'?'sun':'moon');$('#refresh-btn').innerHTML=I('refresh');$('#logout-btn').innerHTML=I('logout');$('#menu-btn').innerHTML=I('menu')}
setChromeIcons();
if(UI.token)showApp();else showLogin();
